CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, zitadel_sub TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL);
ALTER TABLE users ADD CONSTRAINT users_zitadel_sub_unique UNIQUE (zitadel_sub);
CREATE TABLE IF NOT EXISTS catalog_items (id uuid PRIMARY KEY, created_by uuid NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_catalog_items_created_by__id FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS catalog_item_revisions (id BIGSERIAL PRIMARY KEY, catalog_item_id uuid NOT NULL, "name" VARCHAR(200) NOT NULL, unit VARCHAR(10) NOT NULL, edited_by uuid NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_catalog_item_revisions_catalog_item_id__id FOREIGN KEY (catalog_item_id) REFERENCES catalog_items(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_catalog_item_revisions_edited_by__id FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX catalog_item_revisions_catalog_item_id_id ON catalog_item_revisions (catalog_item_id, id);
CREATE TABLE IF NOT EXISTS user_display_names (id BIGSERIAL PRIMARY KEY, user_id uuid NOT NULL, display_name VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_user_display_names_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX user_display_names_user_id_id ON user_display_names (user_id, id);
CREATE TABLE IF NOT EXISTS households (id uuid PRIMARY KEY, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS products (id uuid PRIMARY KEY, household_id uuid NOT NULL, catalog_item_id uuid NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_products_household_id__id FOREIGN KEY (household_id) REFERENCES households(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_products_catalog_item_id__id FOREIGN KEY (catalog_item_id) REFERENCES catalog_items(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
ALTER TABLE products ADD CONSTRAINT uq_products_household_catalog UNIQUE (household_id, catalog_item_id);
CREATE TABLE IF NOT EXISTS product_archives (id BIGSERIAL PRIMARY KEY, product_id uuid NOT NULL, archived_by uuid NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_product_archives_product_id__id FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_product_archives_archived_by__id FOREIGN KEY (archived_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX product_archives_product_id_id ON product_archives (product_id, id);
CREATE TABLE IF NOT EXISTS product_minimum_stocks (id BIGSERIAL PRIMARY KEY, product_id uuid NOT NULL, minimum_stock INT NOT NULL, edited_by uuid NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_product_minimum_stocks_product_id__id FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_product_minimum_stocks_edited_by__id FOREIGN KEY (edited_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT check_product_minimum_stocks_0 CHECK (minimum_stock >= 0));
CREATE INDEX product_minimum_stocks_product_id_id ON product_minimum_stocks (product_id, id);
CREATE TABLE IF NOT EXISTS household_memberships (id BIGSERIAL PRIMARY KEY, household_id uuid NOT NULL, user_id uuid NOT NULL, "role" VARCHAR(20) NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_household_memberships_household_id__id FOREIGN KEY (household_id) REFERENCES households(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_household_memberships_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE INDEX household_memberships_household_id_id ON household_memberships (household_id, id);
CREATE INDEX household_memberships_user_id_id ON household_memberships (user_id, id);
CREATE TABLE IF NOT EXISTS household_membership_revocations (id BIGSERIAL PRIMARY KEY, membership_id BIGINT NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_household_membership_revocations_membership_id__id FOREIGN KEY (membership_id) REFERENCES household_memberships(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS stock_movements (id BIGSERIAL PRIMARY KEY, product_id uuid NOT NULL, "type" VARCHAR(20) NOT NULL, quantity INT NOT NULL, occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, acted_by uuid NOT NULL, note TEXT DEFAULT '' NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_stock_movements_product_id__id FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_stock_movements_acted_by__id FOREIGN KEY (acted_by) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT check_stock_movements_0 CHECK (quantity > 0));
CREATE INDEX stock_movements_product_id_id ON stock_movements (product_id, id);
CREATE SEQUENCE IF NOT EXISTS catalog_item_revisions_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS user_display_names_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS product_archives_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS product_minimum_stocks_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS household_membership_revocations_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS household_memberships_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS stock_movements_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;